import {
  Body,
  Container,
  Head as EmailHead,
  Html,
  Img,
  Preview,
  Text,
  Section,
  Row,
  Column,
  Link,
  Heading,
} from "jsx-email";
import { Fragment } from "react";

import { DefaultFonts } from "@/components/email/font-default";
import { EmailTailwind } from "@/components/email/email-theme";
import type { EmailTheme } from "@/components/email/email-theme";
import { emailAsset } from "@/components/email/email-assets";
import { defaultTheme } from "@/components/email/theme-default";

export type CouponsWithContentOverlayedVariant =
  | "split"
  | "centered"
  | "code-bottom";

export interface CouponsWithContentOverlayedProps {
  theme?: EmailTheme;
  overline?: string;
  discount?: string;
  code?: string;
  expiry?: string;
  backgroundImageSrc?: string;
  buttonLabel?: string;
  buttonHref?: string;
  arrowIconSrc?: string;
  pageBackgroundColor?: string;
  headingColor?: string;
  codeBackgroundColor?: string;
  codeColor?: string;
  buttonBackgroundColor?: string;
  buttonColor?: string;
  variant?: CouponsWithContentOverlayedVariant;
}

const fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

const responsiveStyles = `
  @media only screen and (max-width: 599px) {
    .coupon-overlay-impact { font-size: 60px !important; }
    .coupon-overlay-inline { font-size: 36px !important; }
    .coupon-overlay-split-space { line-height: 192px !important; }
    .coupon-overlay-centered-space { line-height: 152px !important; }
    .coupon-overlay-bottom-space { line-height: 160px !important; }
  }
`;

const sharedDefaults = {
  arrowIconSrc: emailAsset("icon-arrow-right.png"),
  buttonBackgroundColor: "#030712",
  buttonColor: "#fffffe",
  buttonHref: "https://example.com",
  buttonLabel: "Shop now",
  code: "WINTER20OFF",
  codeBackgroundColor: "#fffffe",
  codeColor: "#030712",
  discount: "20% OFF",
  expiry: "until 31/10/2025",
  headingColor: "#fffffe",
  overline: "Our biggest sale of the year",
  pageBackgroundColor: "#f1f5f9",
};

const backgrounds: Record<CouponsWithContentOverlayedVariant, string> = {
  centered: emailAsset("coupons/bg-image-6.jpg"),
  "code-bottom": emailAsset("coupons/bg-image-4.jpg"),
  split: emailAsset("coupons/bg-image-5.jpg"),
};

type SectionProps = Omit<CouponsWithContentOverlayedProps, "theme">;

type ResolvedProps = typeof sharedDefaults & SectionProps;

const Overline = ({
  bold,
  dark,
  props,
}: {
  bold: boolean;
  dark: boolean;
  props: ResolvedProps;
}) => (
  <Text
    style={{
      color: dark ? "#030712" : props.headingColor,
      fontFamily,
      fontSize: "16px",
      fontWeight: bold ? undefined : 500,
      lineHeight: "24px",
      margin: 0,
      textAlign: "center",
      textTransform: "uppercase",
    }}
  >
    {bold && props.overline === sharedDefaults.overline ? (
      <>
        Our <strong>biggest sale</strong> of the year
      </>
    ) : (
      props.overline
    )}
  </Text>
);

const CodeBlock = ({ props }: { props: ResolvedProps }) => (
  <>
    <Text
      style={{
        color: props.headingColor,
        fontFamily,
        fontSize: "16px",
        lineHeight: "24px",
        margin: "24px 0 12px",
        textAlign: "center",
        textTransform: "uppercase",
      }}
    >
      Your code:
    </Text>
    <Section align="center" style={{ margin: "0 auto" }}>
      <Fragment>
        <Row>
          <Column
            style={{
              backgroundColor: props.codeBackgroundColor,
              borderRadius: "8px",
              color: props.codeColor,
              fontFamily,
              fontSize: "16px",
              lineHeight: "24px",
              padding: "8px 16px",
            }}
          >
            {props.code}
          </Column>
        </Row>
      </Fragment>
    </Section>
  </>
);

const CouponButton = ({ props }: { props: ResolvedProps }) => (
  <Section style={{ textAlign: "center" }}>
    <Link
      href={props.buttonHref}
      style={{
        backgroundColor: props.buttonBackgroundColor,
        borderRadius: "8px",
        color: props.buttonColor,
        display: "inline-block",
        fontFamily,
        fontSize: "16px",
        fontWeight: 500,
        lineHeight: 1,
        padding: "14px 20px",
        textDecoration: "none",
      }}
    >
      <span style={{ marginRight: "8px" }}>{props.buttonLabel}</span>
      <span>
        <Img
          alt=""
          src={props.arrowIconSrc}
          style={{
            display: "inline",
            maxWidth: "100%",
            verticalAlign: "baseline",
          }}
          width={12}
        />
      </span>
    </Link>
  </Section>
);

export const CouponsWithContentOverlayedSection = (props: SectionProps) => {
  const variant = props.variant ?? "code-bottom";
  const resolved = {
    ...sharedDefaults,
    backgroundImageSrc: backgrounds[variant],
    ...props,
  } as ResolvedProps;
  const centered = variant === "centered";
  const split = variant === "split";
  return (
    <Section
      style={{ backgroundColor: resolved.pageBackgroundColor }}
      width="100%"
    >
      <Fragment>
        <Row>
          <Column>&zwj;</Column>
          <Column
            style={{
              backgroundImage: `url('${resolved.backgroundImageSrc}')`,
              backgroundPosition: "center",
              backgroundRepeat: "no-repeat",
              backgroundSize: "cover",
              maxWidth: "100%",
              width: "600px",
            }}
          >
            {centered ? (
              <Section
                className="coupon-overlay-centered-space"
                style={{ lineHeight: "182px" }}
              >
                &zwj;
              </Section>
            ) : null}
            {!centered && !split ? (
              <Section
                className="coupon-overlay-bottom-space"
                style={{ lineHeight: "216px" }}
              >
                &zwj;
              </Section>
            ) : null}
            {split ? (
              <Section style={{ lineHeight: "44px" }}>&zwj;</Section>
            ) : null}
            <Overline bold={!centered} dark={centered} props={resolved} />
            {(() => {
              if (split) {
                return (
                  <Heading
                    className="coupon-overlay-inline"
                    style={{
                      color: resolved.headingColor,
                      fontFamily,
                      fontSize: "48px",
                      fontWeight: 500,
                      lineHeight: "normal",
                      margin: 0,
                      textAlign: "center",
                    }}
                    as="h3"
                  >
                    {resolved.discount === sharedDefaults.discount
                      ? "An extra 20% OFF"
                      : resolved.discount}
                  </Heading>
                );
              }
              return (
                <Heading
                  className="coupon-overlay-impact"
                  style={{
                    color: centered ? "#030712" : resolved.headingColor,
                    fontFamily,
                    fontSize: "96px",
                    fontWeight: 500,
                    lineHeight: "normal",
                    margin: 0,
                    textAlign: "center",
                  }}
                  as="h3"
                >
                  {centered && resolved.discount === sharedDefaults.discount ? (
                    <>
                      20% <span style={{ fontWeight: 100 }}>OFF</span>
                    </>
                  ) : (
                    resolved.discount
                  )}
                </Heading>
              );
            })()}
            {centered ? (
              <Text
                style={{
                  color: "#030712",
                  fontFamily,
                  fontSize: "16px",
                  lineHeight: "24px",
                  margin: 0,
                  textAlign: "center",
                }}
              >
                {resolved.expiry}
              </Text>
            ) : (
              <CodeBlock props={resolved} />
            )}
            {(() => {
              if (split) {
                return (
                  <Section
                    className="coupon-overlay-split-space"
                    style={{ lineHeight: "274px" }}
                  >
                    &zwj;
                  </Section>
                );
              }
              return (
                <Section style={{ lineHeight: centered ? "24px" : "44px" }}>
                  &zwj;
                </Section>
              );
            })()}
            {split ? (
              <Section style={{ lineHeight: "44px" }}>&zwj;</Section>
            ) : null}
            <CouponButton props={resolved} />
            {centered ? (
              <Section
                className="coupon-overlay-centered-space"
                style={{ lineHeight: "182px" }}
              >
                &zwj;
              </Section>
            ) : (
              <Section style={{ lineHeight: "44px" }}>&zwj;</Section>
            )}
          </Column>
          <Column>&zwj;</Column>
        </Row>
      </Fragment>
    </Section>
  );
};

export const CouponsWithContentOverlayed = ({
  pageBackgroundColor = "#f1f5f9",
  theme = defaultTheme,
  variant = "code-bottom",
  ...props
}: CouponsWithContentOverlayedProps) => (
  <Html>
    <EmailHead>
      <DefaultFonts />
      <style dangerouslySetInnerHTML={{ __html: responsiveStyles }} />
    </EmailHead>
    <Preview>Our biggest sale of the year</Preview>
    <EmailTailwind theme={theme}>
      <Body
        style={{ backgroundColor: pageBackgroundColor, fontFamily }}
        className="m-0"
      >
        <Container className="mx-auto max-w-[600px] w-[600px]">
          <CouponsWithContentOverlayedSection
            {...props}
            pageBackgroundColor={pageBackgroundColor}
            variant={variant}
          />
        </Container>
      </Body>
    </EmailTailwind>
  </Html>
);

CouponsWithContentOverlayed.PreviewProps = {
  theme: defaultTheme,
  variant: "code-bottom",
} satisfies CouponsWithContentOverlayedProps;

const ASSET_ORIGIN = "https://www.emailcn.run";

const palettes = [
  ["4F46E5", "FFFFFF"],
  ["0F766E", "FFFFFF"],
  ["C2410C", "FFFFFF"],
  ["7E22CE", "FFFFFF"],
  ["0369A1", "FFFFFF"],
  ["BE123C", "FFFFFF"],
] as const;

const hashString = (value: string) => {
  let hash = 7;

  for (const character of value) {
    hash = (hash * 31 + (character.codePointAt(0) ?? 0)) % 2_147_483_647;
  }

  return hash;
};

const getDimensions = (path: string) => {
  if (/(?:avatar|user|headshot)/i.test(path)) {
    return [160, 160] as const;
  }
  if (/(?:logo|insignia)/i.test(path)) {
    return [320, 96] as const;
  }
  if (/(?:badge-app|badge-google)/i.test(path)) {
    return [260, 80] as const;
  }
  if (/(?:icon|btc|eth)/i.test(path)) {
    return [64, 64] as const;
  }
  if (/(?:portrait|member|team)/i.test(path)) {
    return [600, 800] as const;
  }
  if (/(?:square|product|shopping-cart)/i.test(path)) {
    return [700, 700] as const;
  }
  if (/(?:hero|footer|background|bg-|overlay|full-width)/i.test(path)) {
    return [1200, 700] as const;
  }
  if (/(?:strip|landscape|bento|category-preview)/i.test(path)) {
    return [800, 520] as const;
  }

  return [800, 600] as const;
};

const getLabel = (path: string) => {
  const fileName = path.split("/").at(-1) ?? "emailcn";

  return fileName
    .replace(/\.[^.]+$/, "")
    .replace(/^(?:logo|badge|icon)-/, "")
    .replaceAll("-", " ")
    .replaceAll(/\b\w/g, (character) => character.toUpperCase());
};

const getSeed = (path: string) =>
  `emailcn-${path
    .replace(/\.[^.]+$/, "")
    .replaceAll(/[^a-z0-9]+/gi, "-")
    .replaceAll(/^-|-$/g, "")
    .toLowerCase()}`;

export const emailAsset = (path: string) => {
  const normalizedPath = path.replace(/^\/+/, "");

  if (
    normalizedPath === "bento-grids/trend.png" ||
    normalizedPath === "bento-grids/trend-sm.png"
  ) {
    return `${ASSET_ORIGIN}/email-assets/${normalizedPath}`;
  }

  const seed = getSeed(normalizedPath);
  const hash = hashString(seed);
  const [background, foreground] =
    palettes[hash % palettes.length] ?? palettes[0];
  const [width, height] = getDimensions(normalizedPath);

  if (/(?:avatar|user|headshot|member|team)/i.test(normalizedPath)) {
    return `https://api.dicebear.com/9.x/lorelei/png?seed=${encodeURIComponent(
      seed
    )}&size=${Math.max(width, height)}&backgroundColor=${background.toLowerCase()}`;
  }

  if (/(?:trend|chart)/i.test(normalizedPath)) {
    return `${ASSET_ORIGIN}/email-assets/bento-grids/trend.png`;
  }

  if (
    /(?:icon|btc|eth|logo|insignia|badge-app|badge-google)/i.test(
      normalizedPath
    )
  ) {
    return `https://placehold.co/${width}x${height}/${background}/${foreground}.png?text=${encodeURIComponent(
      getLabel(normalizedPath)
    )}`;
  }

  return `https://picsum.photos/seed/${encodeURIComponent(
    seed
  )}/${width}/${height}.jpg`;
};
